package com.fakelegacy.order.service;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Map;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import com.fakelegacy.order.client.CatalogClient;
import com.fakelegacy.order.domain.ProductCache;
import com.fakelegacy.order.repo.ProductCacheRepository;

@Service
public class ProductCacheService {

    private static final Logger log = LoggerFactory.getLogger(ProductCacheService.class);

    @Autowired
    private ProductCacheRepository repository;

    @Autowired
    private CatalogClient catalogClient;

    /** Cache first, REST fallback on a miss; null when the catalog does not know the SKU. */
    public ProductCache find(String sku) {
        ProductCache cached = repository.findById(sku).orElse(null);
        if (cached != null) {
            return cached;
        }
        Map<String, Object> raw = catalogClient.getProduct(sku);
        if (raw == null) {
            return null;
        }
        return remember(raw);
    }

    public ProductCache remember(Map<String, Object> raw) {
        ProductCache pc = new ProductCache();
        pc.setSku(String.valueOf(raw.get("sku")));
        pc.setCategory(String.valueOf(raw.get("category")));
        pc.setWeightKg(new BigDecimal(String.valueOf(raw.get("weightKg"))));
        pc.setRefreshedAt(LocalDateTime.now());
        return repository.save(pc);
    }

    @Scheduled(initialDelay = 60000, fixedDelay = 300000)
    public void refreshAll() {
        try {
            for (Map<String, Object> raw : catalogClient.listProducts()) {
                remember(raw);
            }
        } catch (RuntimeException e) {
            log.warn("product cache refresh skipped: {}", e.getMessage());
        }
    }
}
